     "ex": "eval case (one line of a JSONL test set)\n{\"id\": \"c017\", \"input\": \"الشحنة اتأخرت أسبوع ومحدش بيرد\", \"expected\": \"shipping\",\n \"tags\": [\"arabic\", \"angry\"], \"source\": \"real ticket 2026-09, anonymised\"}",
